import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";

/**
 * Deny by default: a tool skips approval only when GitHub's MCP server annotates it with
 * `readOnlyHint: true` (the server sets it explicitly on every read tool). Write tools, and any
 * tool without that annotation, need human approval.
 */
export function githubToolNeedsApproval({
  annotations,
}: Pick<RequireToolApprovalContext, "annotations">): boolean {
  return annotations?.readOnlyHint !== true;
}

// GitHub's official remote MCP server: https://github.com/github/github-mcp-server
// Auth: a personal access token in GITHUB_PAT. Writes are enabled, but every non-read tool
// call suspends for human approval (see githubToolNeedsApproval). The toolset header limits
// the server to repos, issues, PRs and Actions so the model sees a small tool surface.
export const githubMcp = new MCPClient({
  id: "github",
  servers: {
    github: {
      url: new URL("https://api.githubcopilot.com/mcp/"),
      requestInit: {
        headers: {
          Authorization: `Bearer ${process.env.GITHUB_PAT}`,
          "X-MCP-Toolsets": "context,repos,issues,pull_requests,actions",
        },
      },
      // Refuse to follow redirects/requests to any other host with the token attached.
      allowedHosts: ["api.githubcopilot.com"],
      requireToolApproval: githubToolNeedsApproval,
    },
  },
});

type GithubTools = Awaited<ReturnType<typeof githubMcp.listTools>>;
let cached: GithubTools | undefined;

/**
 * Resolves the GitHub MCP tools lazily (the agent calls this per request). Degrades to no tools
 * (logging a warning) when GITHUB_PAT is missing or the connection fails, so the server still
 * boots without a token. Only a successful fetch is cached, so a later retry can recover.
 */
export async function getGithubTools(): Promise<GithubTools> {
  if (cached) return cached;
  if (!process.env.GITHUB_PAT) {
    console.warn("[github] GITHUB_PAT is not set; the GitHub agent has no tools");
    return {};
  }
  try {
    // listTools() reports a failed server as an empty result instead of throwing; don't cache that.
    const tools = await githubMcp.listTools();
    if (Object.keys(tools).length > 0) cached = tools;
    return tools;
  } catch (error) {
    console.warn("[github] could not load GitHub MCP tools:", error instanceof Error ? error.message : error);
    return {};
  }
}

const TOOL_KEY_PREFIX = "github_"; // listTools() namespaces tools as `<server>_<tool>`.

/**
 * Only the tools that never need approval, for callers that cannot show an approval prompt
 * (delegation from the assistant, and therefore the WhatsApp bot). Same predicate as the
 * approval gate, so a tool is either listed here or would have suspended for approval.
 */
export async function getGithubReadTools(): Promise<GithubTools> {
  const tools = await getGithubTools();
  return Object.fromEntries(
    Object.entries(tools).filter(([key, tool]) => {
      if (!key.startsWith(TOOL_KEY_PREFIX)) return false;
      const annotations = (tool as { mcp?: { annotations?: RequireToolApprovalContext["annotations"] } }).mcp?.annotations;
      return !githubToolNeedsApproval({ annotations });
    }),
  );
}
import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { GITHUB_INSTRUCTIONS, GITHUB_READER_INSTRUCTIONS } from "../prompts";
import { getGithubReadTools, getGithubTools } from "../tools/github";

/**
 * Chatted with directly in the web app. Has every GitHub tool; each mutating call suspends
 * for the user's approval, which the web chat shows inline (see githubToolNeedsApproval).
 */
export const githubAgent = wrapMastra(new Agent({
  id: "github",
  name: "GitHub Agent",
  description:
    "Inspects GitHub repositories, issues, pull requests, and Actions runs, and makes changes (issues, comments, branches, files, pull requests, reviews, merges) when asked. Every change is shown with its exact arguments and runs only after you approve it.",
  instructions: GITHUB_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  // Resolved per request so a missing token or GitHub outage never blocks server startup.
  tools: () => getGithubTools(),
  defaultOptions: { maxSteps: 12 },
}));

/**
 * Read-only twin used only for the assistant's delegation (and so the WhatsApp bot). Those
 * paths have no approval UI, so it never receives a tool that could suspend for approval.
 * Not registered on Mastra: it is not a chat target and does not appear in the agent list.
 */
export const githubReaderAgent = wrapMastra(new Agent({
  id: "github-reader",
  name: "GitHub Agent",
  description:
    "Read-only inspection of GitHub repositories, issues, pull requests, and Actions runs. Returns concise findings with issue/PR numbers and links. Cannot create, edit, comment, merge, or trigger anything. Delegate GitHub lookups here.",
  instructions: GITHUB_READER_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  tools: () => getGithubReadTools(),
  defaultOptions: { maxSteps: 12 },
}));
import { resolve } from "node:path";
import { Mastra } from "@mastra/core/mastra";
import { LibSQLStore } from "@mastra/libsql";
import { dataDir } from "../data-dir";
import "../telemetry";
import { assistant } from "./agents/assistant";
import { marketResearcher } from "./agents/market-researcher";
import { cfoAgent } from "./agents/cfo";
import { githubAgent } from "./agents/github";

export const mastra = new Mastra({
  storage: new LibSQLStore({ id: "mastra", url: `file:${resolve(dataDir(), "mastra.db")}` }),
  agents: { assistant, marketResearcher, cfoAgent, githubAgent },
});
import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { ASSISTANT_INSTRUCTIONS } from "../prompts";
import { marketResearcher } from "./market-researcher";
import { cfoAgent } from "./cfo";
import { githubReaderAgent } from "./github";

export const assistant = wrapMastra(new Agent({
  id: "assistant",
  name: "Assistant",
  description: "Primary assistant that handles conversations and coordinates specialist agents.",
  instructions: ASSISTANT_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  // Delegation gets the read-only GitHub agent: neither the assistant's web chat nor WhatsApp can
  // show an approval prompt for a sub-agent's write. Writes happen in the GitHub agent's own chat.
  // The key stays "githubAgent" so the prompt and the web UI's "agent-githubAgent" label still match.
  agents: { marketResearcher, cfoAgent, githubAgent: githubReaderAgent },
  defaultOptions: {
    maxSteps: 6,
    delegation: {
      onDelegationStart: () => ({ modifiedMaxSteps: 12 }),
    },
  },
}));
import type { ServerResponse } from "node:http";
import type { Role } from "./index";
import type { SessionUser } from "./session";

export type AgentAccess = "all" | "admin";

// Keyed by Mastra agent id. To make a future agent admin-only, add its id here as "admin".
const agentAccess: Record<string, AgentAccess> = {
  assistant: "all",
  "market-researcher": "all",
  cfo: "all",
  github: "all",
};

// Admins can use every agent; everyone else only agents marked "all" (unlisted agents default to "all").
export function canUseAgent(user: SessionUser, agentId: string): boolean {
  if (user.role === "admin") return true;
  return (agentAccess[agentId] ?? "all") === "all";
}

// Guard for admin-only routes: sends 403 and returns false when the user lacks the role (admin satisfies any role).
// Responds inline (not via chat-api's sendJson) to keep the auth module free of mastra imports.
export function requireRole(user: SessionUser, res: ServerResponse, role: Role): boolean {
  if (user.role === "admin" || user.role === role) return true;
  res.writeHead(403, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify({ error: "Forbidden" }));
  return false;
}
